INSERT INTO `faq` VALUES (1,'Thông tin chung','Địa chỉ trường ở đâu? UTH có mấy cơ sở? Trường nằm ở chỗ nào?','Trường Đại học Giao thông Vận tải TP.HCM (UTH) có cơ sở chính tại Số 2, Đường Võ Oanh, Phường 25, Quận Bình Thạnh, TP.HCM. Ngoài ra, trường còn có các cơ sở đào tạo khác tại Quận 12 (TP.HCM), TP. Thủ Đức và TP. Vũng Tàu.','/thong-tin-truong'),(2,'Chương trình Đào tạo','Trường có những ngành gì? Ngành CNTT học hệ nào? Đào tạo chất lượng cao là sao?','UTH là trường công lập đào tạo đa ngành hàng đầu về Giao thông vận tải, Logistics, Công nghệ thông tin, Khoa học dữ liệu, Điện tử viễn thông, Kinh tế vận tải và Kỹ thuật công trình. Hệ đào tạo gồm 2 loại hình: Hệ Đại trà và Hệ Chất lượng cao.','/chuong-trinh-khung'),(3,'Cách Tính Điểm','Cách tính điểm môn học thế nào? Điểm F là gì? Quy chế thang điểm chữ?','UTH áp dụng đào tạo theo hệ thống tín chỉ. Điểm tổng kết môn gồm: Điểm quá trình và Điểm thi kết thúc học phần. Điểm tính theo thang điểm 10 rồi quy đổi sang thang điểm chữ (A, B, C, D, F) tương ứng với thang điểm 4. Điểm F là rớt môn và bắt buộc phải đóng tiền đăng ký học lại.','/ket-qua-hoc-tap'),(4,'Học Cải Thiện','Điểm thấp có được học lại không? Làm sao để nâng điểm tích lũy?','Sinh viên đạt điểm trung bình môn ở mức D, D+, C, C+ muốn nâng cao điểm trung bình tích lũy (GPA) được phép đăng ký học cải thiện vào các học kỳ tiếp theo. Khi học cải thiện, điểm của lần học sau sẽ thay thế hoàn toàn cho điểm của lần học trước.','/ket-qua-hoc-tap'),(5,'Cảnh Báo Học Vụ','Điều kiện xét nâng lớp? Khi nào bị cảnh báo học vụ? Bị buộc thôi học khi nào?','Sinh viên sẽ bị cảnh báo học vụ nếu điểm trung bình tích lũy học kỳ đạt dưới 0.8 (đối với học kỳ đầu tiên) hoặc dưới 1.0 (đối với các học kỳ tiếp theo), hoặc số tín chỉ bị nợ vượt quá quy định. Bị cảnh báo học vụ 2 lần liên tiếp sẽ thuộc diện xem xét buộc thôi học.','/thong-tin-ca-nhan'),(6,'Đăng Ký Môn Học','Khi nào đăng ký học phần? Một kỳ được đăng ký tối đa bao nhiêu tín chỉ? Hủy môn học ở đâu?','Sinh viên thực hiện đăng ký học phần (DKMH) trực tuyến tại trang Portal UTH theo khung thời gian thông báo của Phòng Đào tạo. Sinh viên hệ đại trà được đăng ký tối đa 24 tín chỉ và tối thiểu 14 tín chỉ trong một học kỳ chính.','/dang-ky-hoc-phan'),(7,'Môn Điều Kiện','Môn tiên quyết là gì? Môn học trước là gì? Khác nhau thế nào?','Môn tiên quyết là môn sinh viên bắt buộc phải học và thi đạt (điểm chữ từ D trở lên) mới được đăng ký môn tiếp theo. Môn học trước là môn sinh viên chỉ cần hoàn thành khóa học (kể cả thi rớt điểm F) là đã đủ điều kiện đăng ký môn sau.','/dang-ky-mon-hoc-dieu-kien'),(8,'Quy Chế Thi Cử','Xem lịch thi ở đâu? Vào phòng thi cần mang gì? Hoãn thi làm sao?','Lịch thi học kỳ được công bố trên Portal trước kỳ thi 2 tuần. Khi vào phòng thi, sinh viên bắt buộc phải xuất trình Thẻ sinh viên chính thức hoặc giấy tờ tùy thân có ảnh (CCCD). Sinh viên vắng thi không có lý do chính đáng sẽ nhận điểm 0.','/lich-hoc-trong-tuan'),(9,'Học Phí Trường','Học phí một tín chỉ bao nhiêu tiền? Đóng tiền học ở đâu?','Mức thu học phí UTH được tính theo tổng số tín chỉ sinh viên đăng ký trong kỳ. Hiện tại, hệ đại trà dao động khoảng 350.000đ - 420.000đ/tín chỉ, hệ chất lượng cao khoảng 750.000đ - 850.000đ/tín chỉ. Sinh viên nộp tiền trực tuyến qua Cổng thanh toán của trường.','/cong-thanh-toan'),(10,'Gia Hạn Học Phí','Không có tiền đóng học phí làm sao? Xin nợ học phí ở đâu?','Sinh viên có hoàn cảnh khó khăn không thể hoàn thành học phí đúng hạn phải làm Đơn xin gia hạn học phí trực tuyến gửi Phòng Công tác sinh viên trước thời hạn quy định để không bị khóa tài khoản đăng ký môn học và bị cấm thi.','/tra-cuu-cong-no'),(11,'Hoạt Động Đoàn Hội','Lịch hiến máu tình nguyện? Tham gia hoạt động được cộng bao nhiêu điểm rèn luyện?','Ngày hội hiến máu tình nguyện trường UTH được tổ chức định kỳ hàng năm tại Sảnh lớn khu giảng đường A. Sinh viên tham gia hiến máu nhân đạo sẽ được cấp giấy chứng nhận, hỗ trợ chi phí và được cộng 5 điểm rèn luyện (ĐRL) vào mục hoạt động cộng đồng.','/thong-bao-su-kien'),(12,'Các Câu Lạc Bộ','Trường có CLB guitar không? Đội tình nguyện hoạt động thế nào?','UTH hiện có hơn 20 Câu lạc bộ (CLB) sinh viên đang hoạt động thuộc các khối: Học thuật (CLB Tin học, CLB Logistics), Nghệ thuật (CLB Guitar, CLB Bước Nhảy), Thể thao (CLB Bóng đá, Bóng chuyền) và Tình nguyện (Đội Công tác xã hội, CLB Tiếp sức đến trường).','/thong-bao-su-kien'),(13,'Học Bổng Khuyến Khích','Điều kiện nhận học bổng trường? Điểm rèn luyện bao nhiêu thì được học bổng?','Học bổng khuyến khích học tập UTH được xét sau mỗi học kỳ dựa trên 2 tiêu chí song song: Điểm trung bình học tập đạt loại Khá trở lên (từ 2.5/4.0) và Điểm rèn luyện đạt loại Tốt trở lên (từ 80 điểm/100), đồng thời không bị kỷ luật và không nợ môn.','/thong-bao-su-kien'),(14,'Chuẩn Đầu Ra Ngoại Ngữ','Chuẩn tiếng Anh xét tốt nghiệp? Nộp bằng TOEIC ở đâu? Điều kiện miễn học Anh văn?','Sinh viên đại học chính quy UTH phải đạt chuẩn đầu ra tiếng Anh theo quy định (thường là TOEIC 450 trở lên hoặc B1 VSTEP tùy theo ngành học). Chứng chỉ phải còn giá trị hiệu lực và nộp về Trung tâm Ngoại ngữ trường để làm thủ tục hậu kiểm xét tốt nghiệp.','/dich-vu-sinh-vien'),(15,'Chuẩn Tin Học','Chuẩn tin học đầu ra là gì? Chứng chỉ MOS hay IC3?','Sinh viên UTH bắt buộc phải hoàn thành chuẩn đầu ra Tin học bằng việc đạt chứng chỉ Tin học đại chúng đại học hoặc các chứng chỉ quốc tế được công nhận tương đương như MOS (đạt 3 kỹ năng Word, Excel, Powerpoint) hoặc IC3.','/dich-vu-sinh-vien'),(16,'Điều Kiện Tốt Nghiệp','Làm sao để được ra trường? Điều kiện xét tốt nghiệp UTH? Nợ môn có được xét tốt nghiệp?','Điều kiện xét công nhận tốt nghiệp UTH: Tích lũy đủ số tín chỉ của chương trình khung; Điểm trung bình tích lũy (GPA) toàn khóa đạt từ 2.0/4.0 trở lên; Đạt chuẩn đầu ra Ngoại ngữ và Tin học; Đạt chứng chỉ Giáo dục quốc phòng và Giáo dục thể chất; Không trong thời gian bị kỷ luật.','/chuong-trinh-khung'),(17,'Mất Thẻ Sinh Viên','Làm lại thẻ sinh viên ở đâu? Mất thẻ sinh viên đóng phạt bao nhiêu?','Khi bị mất thẻ, sinh viên đến Phòng Công tác sinh viên (Cơ sở chính, khu nhà A) để làm thủ tục xin cấp lại thẻ sinh viên mới. Lệ phí cấp lại thẻ theo quy định là 50.000đ. Trong thời gian chờ cấp thẻ mới, sinh viên được cấp giấy xác nhận tạm thời để ra vào trường.','/dich-vu-sinh-vien'),(18,'Ký Túc Xá Trường','Đăng ký ở KTX ở đâu? Chi phí Ký túc xá UTH? Đối tượng ưu tiên ở KTX?','UTH hỗ trợ chỗ ở tại Ký túc xá trường cho sinh viên (ưu tiên sinh viên diện chính sách, vùng sâu vùng xa, hoàn cảnh khó khăn). Sinh viên làm Đơn đăng ký nội trú trực tuyến trên Portal hoặc nộp hồ sơ trực tiếp tại Ban quản lý Ký túc xá trong thời gian quy định đầu năm học.','/thong-bao-su-kien'),(19,'Mượn Sách Thư Viện','Thư viện trường ở đâu? Cách mượn sách về nhà? Trả sách trễ hạn bị phạt thế nào?','Thư viện UTH đặt tại khu vực cơ sở chính. Sinh viên sử dụng Thẻ sinh viên để vào thư viện đọc sách hoặc làm thủ tục mượn tài liệu về nhà. Thời gian mượn tối đa là 2 tuần/cuốn. Nếu trả sách trễ hạn, sinh viên sẽ bị phạt tiền theo quy định của thư viện.','/dich-vu-sinh-vien'),(20,'Bảo Hiểm Y Tế','Đóng tiền bảo hiểm y tế ở đâu? Hạn chót nộp BHYT? Gia hạn bảo hiểm sinh viên?','Bảo hiểm y tế (BHYT) là hình thức bắt buộc đối với tất cả sinh viên. Nhà trường tổ chức thu tiền và gia hạn BHYT định kỳ vào đầu năm học thông qua Cổng thanh toán trực tuyến. Sinh viên có thẻ BHYT diện hộ nghèo, thân nhân quân nhân phải nộp bản photo minh chứng để được miễn giảm.','/cong-thanh-toan'),(21,'Sinh Viên 5 Tốt','Tiêu chí đạt Sinh viên 5 Tốt? Quyền lợi khi đạt Sinh viên 5 Tốt UTH?','Danh hiệu Sinh viên 5 Tốt được xét duyệt hàng năm dựa trên 5 tiêu chí: Học tập tốt (GPA >= 3.2 hoặc 2.8 tùy hệ), Đạo đức tốt (ĐRL >= 80), Thể lực tốt (đạt danh hiệu khỏe), Tình nguyện tốt (tham gia chiến dịch lớn), và Hội nhập tốt (đạt giải thưởng khoa học hoặc kỹ năng ngoại ngữ tốt).','/thong-bao-su-kien'),(22,'Nghiên Cứu Khoa Học','Đăng ký nghiên cứu khoa học ở đâu? Quyền lợi khi làm NCKH sinh viên?','Phong trào Nghiên cứu khoa học (NCKH) sinh viên UTH được phát động vào đầu học kỳ 1. Sinh viên đăng ký đề tài theo nhóm (dưới sự hướng dẫn của giảng viên) thông qua Phòng Quản lý khoa học. Đề tài nghiệm thu đạt loại Khá trở lên sẽ được cộng điểm rèn luyện và thưởng tiền mặt.','/thong-bao-su-kien'),(23,'Rút Học Phần, Hủy Môn','Cách rút môn học? Hạn chót hủy học phần đã đăng ký? Rút môn có được hoàn tiền không?','Trong 2 tuần đầu của học kỳ chính (hoặc 1 tuần đối với học kỳ hè), sinh viên được phép nộp đơn online để xin rút bớt học phần đã đăng ký. Học phần xin rút thành công sẽ ghi nhận điểm chữ W trên bảng điểm, không tính vào điểm trung bình tích lũy nhưng sinh viên không được hoàn lại học phí.','/dang-ky-hoc-phan'),(24,'Phòng Công Tác Sinh Viên','Liên hệ phòng CTSV ở đâu? Xin giấy xác nhận sinh viên vay vốn ở đâu?','Phòng Công tác sinh viên (CTSV) chịu trách nhiệm giải quyết các thủ tục: Cấp giấy xác nhận sinh viên để vay vốn ngân hàng, tạm hoãn nghĩa vụ quân sự, đánh giá điểm rèn luyện, giải quyết chế độ chính sách, miễn giảm học phí. Văn phòng đặt tại tầng trệt nhà A cơ sở chính.','/dich-vu-sinh-vien'),(25,'Phòng Đào Tạo','Số điện thoại Phòng Đào tạo? Hỏi về lịch học, lịch thi, xét tốt nghiệp ở đâu?','Phòng Đào tạo UTH là nơi giải quyết các vấn đề chuyên môn về: Khung lịch học, lịch thi, giải quyết đơn phúc khảo điểm thi, cấp bảng điểm chính thức, xử lý hồ sơ chuyển ngành, ngừng học tạm thời, bảo lưu kết quả, và xét công nhận tốt nghiệp.','/thong-tin-truong'),(26,'Ký Túc Xá Quận 12','KTX Quận 12 ở đâu? Đăng ký ký túc xá cơ sở 2? Chi phí phòng KTX Quận 12?','Cơ sở 2 của UTH tại Quận 12 có khu Ký túc xá khang trang dành riêng cho sinh viên học tập tại đây. Chi phí nội trú dao động từ 150.000đ - 250.000đ/tháng/sinh viên tùy loại phòng. Sinh viên nộp đơn đăng ký trực tiếp tại Ban quản lý KTX Cơ sở 2.','/thong-bao-su-kien'),(27,'Học Bổng Doanh Nghiệp','Học bổng tài trợ? Điều kiện nhận học bổng ngoài ngân sách? Học bổng vượt khó?','Ngoài học bổng khuyến khích của trường, sinh viên UTH còn có cơ hội nhận Học bổng tài trợ từ các tập đoàn, doanh nghiệp lớn đối tác (như các tổng công ty xây dựng, cảng biển, công ty công nghệ). Tiêu chí xét tuyển thường ưu tiên sinh viên nghèo vượt khó học giỏi hoặc có thành tích xuất sắc.','/thong-bao-su-kien'),(28,'Các Tuyến Xe Buýt','Xe buýt nào đi qua trường UTH? Đi xe bus đến Võ Oanh? Xe bus qua cơ sở Bình Thạnh?','Cơ sở chính Võ Oanh (Bình Thạnh) có rất nhiều tuyến xe buýt đi qua như tuyến số 08, 14, 19, 43, 44, 93 (dừng tại trạm Điện Biên Phủ hoặc Nguyễn Văn Thương rồi đi bộ vào). Sinh viên được hưởng giá vé ưu đãi khi xuất trình Thẻ sinh viên UTH.','/thong-tin-truong'),(29,'Thủ Tục Chuyển Ngành','Làm sao để đổi ngành học? Điều kiện chuyển ngành UTH? Đang học có được đổi ngành khác?','Sinh viên được xem xét chuyển ngành nếu: Không thuộc diện bị buộc thôi học; Điểm xét tuyển đầu vào không thấp hơn điểm trúng tuyển của ngành muốn chuyển sang; Có đơn xin chuyển ngành và được sự đồng ý của cả hai Khoa chủ quản. Thủ tục làm tại Phòng Đào tạo vào cuối năm học thứ nhất.','/dich-vu-sinh-vien'),(30,'Bảo Lưu Kết Quả','Xin tạm dừng học? Cách làm đơn bảo lưu học tập? Nghỉ học tạm thời được bao lâu?','Sinh viên được xin nghỉ học tạm thời và bảo lưu kết quả học tập vì lý do cá nhân (như sức khỏe, hoàn cảnh gia đình hoặc thực hiện nghĩa vụ quân sự). Thời gian tạm dừng học không quá 2 học kỳ chính và phải làm đơn nộp về Phòng Đào tạo trước khi học kỳ mới bắt đầu.','/dich-vu-sinh-vien'),(31,'Phúc Khảo Điểm Thi','Chấm phúc khảo ở đâu? Lệ phí phúc khảo bài thi? Thời hạn nộp đơn chấm phúc khảo?','Nếu thấy điểm thi kết thúc học phần không chính xác, sinh viên có quyền làm Đơn xin phúc khảo bài thi nộp về Phòng Đào tạo hoặc văn phòng Khoa trong vòng 5 ngày làm việc kể từ ngày công bố điểm. Lệ phí phúc khảo theo quy định hiện hành của trường.','/ket-qua-hoc-tap'),(32,'Đồng Phục & Trang Phục','Quy định đồng phục UTH? Mặc áo gì đi học? Có bắt buộc mặc áo trường không?','Sinh viên khi đến trường UTH phải ăn mặc lịch sự, gọn gàng, không mặc quần đùi, áo ba lỗ, dép lê vào lớp. Nhà trường khuyến khích sinh viên mặc Áo thun đồng phục UTH hoặc áo sơ mi trắng vào các ngày lễ, các buổi sinh hoạt chung và các ngày cố định theo quy định của Khoa.','/thong-bao-su-kien'),(33,'Kỷ Luật Học Đường','Quy chế kỷ luật sinh viên? Đi thi gian lận bị phạt thế nào? Quay cóp bài thi bị xử lý sao?','Sinh viên vi phạm quy chế thi cử (như mang tài liệu, điện thoại vào phòng thi, quay cóp) sẽ bị xử lý kỷ luật nghiêm khắc từ Đình chỉ thi môn đó, Nhận điểm 0, Cảnh cáo trước toàn trường, cho đến đình chỉ học tập có thời hạn hoặc buộc thôi học nếu tái phạm nhiều lần.','/thong-tin-ca-nhan'),(34,'Văn Phòng Khoa CNTT','Liên hệ khoa CNTT ở đâu? Số điện thoại khoa Công nghệ thông tin UTH?','Văn phòng Khoa Công nghệ thông tin UTH chịu trách nhiệm quản lý chuyên môn ngành CNTT và Khoa học dữ liệu. Văn phòng khoa hỗ trợ sinh viên các vấn đề về: Đăng ký đồ án tốt nghiệp, thực tập doanh nghiệp, cố vấn học tập. Địa chỉ liên hệ đặt tại Khu nhà C, Cơ sở chính.','/thong-tin-truong'),(35,'Văn Phòng Khoa Viện','Liên hệ Viện Logistics ở đâu? Văn phòng Khoa Kinh tế vận tải nằm ở đâu?','Các văn phòng Khoa chuyên ngành (như Viện Logistics và Quản lý chuỗi cung ứng, Khoa Kinh tế vận tải, Khoa Công trình giao thông, Khoa Điện - Điện tử viễn thông) đều có văn phòng trực ban tại các khu nhà chức năng cơ sở chính để hỗ trợ giải quyết lịch học chuyên ngành cho sinh viên.','/thong-tin-truong'),(36,'Giáo Dục Quốc Phòng','Học quân sự ở đâu? Lịch học giáo dục quốc phòng? Đi học quân sự cần chuẩn bị gì?','Sinh viên UTH tham gia học môn Giáo dục quốc phòng - An ninh tập trung tại Trung tâm Giáo dục Quốc phòng theo lịch phân bổ của trường. Sinh viên được rèn luyện trong môi trường quân đội nội trú, phải tuân thủ nghiêm ngặt giờ giấc, tác phong quân kỷ và mặc quân phục.','/thong-bao-su-kien'),(37,'Giáo Dục Thể Chất','Học thể dục ở đâu? Các môn thể dục UTH? Đăng ký học môn thể thao nào?','Môn Giáo dục thể chất (Thể dục) tại UTH rất đa dạng, sinh viên được tự chọn đăng ký các môn thể thao yêu thích trên Portal như: Bóng đá, Bóng chuyền, Bóng rổ, Cầu lông, Cờ vua hoặc Võ thuật. Sinh viên phải thi đạt môn này mới đủ điều kiện xét tốt nghiệp.','/dang-ky-hoc-phan'),(38,'Cấp Lại Bảng Điểm','Xin cấp bảng điểm học tập ở đâu? Lệ phí in bảng điểm chính thức?','Sinh viên cần bảng điểm chính thức (có mộc đỏ của trường) để xin việc làm hoặc nộp hồ sơ học bổng phải làm Đơn xin cấp bảng điểm tại máy tự động hoặc nộp trực tiếp tại Phòng Đào tạo. Lệ phí in bảng điểm được tính theo số lượng bản sao quy định.','/dich-vu-sinh-vien'),(39,'Phạt Tiền Thư Viện','Làm mất sách thư viện đền tiền thế nào? Quên trả sách thư viện bị phạt bao nhiêu?','Sinh viên mượn tài liệu thư viện UTH nếu làm mất hoặc hư hỏng phải mua đền cuốn sách mới tương đương hoặc đền tiền gấp nhiều lần giá trị cuốn sách theo quy chế. Trả sách trễ hạn sẽ bị phạt số tiền tính theo từng ngày trễ hạn và bị tạm khóa thẻ thư viện.','/dich-vu-sinh-vien'),(40,'Nguyện Vọng Bổ Sung','Trường có xét tuyển bổ sung không? Điều kiện xét tuyển đợt 2 UTH?','Trong trường hợp các ngành học chưa tuyển đủ chỉ tiêu đợt 1, Hội đồng tuyển sinh UTH sẽ thông báo nhận hồ sơ Xét tuyển nguyện vọng bổ sung (Đợt 2) trên trang tuyển sinh chính thức của trường. Thí sinh nộp hồ sơ theo phương thức xét điểm thi tốt nghiệp THPT hoặc học bạ.','/thong-bao-su-kien'),(41,'Bảng Điểm Tiếng Anh','Xin bảng điểm bằng tiếng Anh ở đâu? Lệ phí dịch thuật bảng điểm UTH? Cấp bảng điểm song ngữ?','Sinh viên có nhu cầu cấp bảng điểm bằng tiếng Anh (hoặc song ngữ) để làm hồ sơ du học, săn học bổng quốc tế hoặc nộp cho doanh nghiệp nước ngoài thì làm đơn đăng ký tại Phòng Đào tạo. Thời gian xử lý và cấp phát từ 3 đến 5 ngày làm việc kèm theo lệ phí in ấn quy định.','/dich-vu-sinh-vien'),(42,'Phúc Khảo Đồ Án','Đồ án tốt nghiệp có được phúc khảo không? Chấm lại điểm khóa luận tốt nghiệp?','Theo quy chế học vụ UTH, điểm bảo vệ Đồ án tốt nghiệp hoặc Khóa luận tốt nghiệp sẽ KHÔNG được chấm phúc khảo. Điểm số cuối cùng do Hội đồng chấm tốt nghiệp quyết định ngay tại buổi bảo vệ công khai. Sinh viên chỉ được quyền khiếu nại nếu có sai sót trong quá trình cộng điểm hoặc nhập điểm vào hệ thống.','/ket-qua-hoc-tap'),(43,'Khóa Tài Khoản Portal','Tại sao tài khoản Portal bị khóa? Lỗi không đăng nhập được trang sinh viên?','Tài khoản Portal của sinh viên UTH thường bị khóa vì các lý do sau: Nợ học phí quá hạn quy định; Chưa hoàn thành các khảo sát bắt buộc của trường; Hoặc nhập sai mật khẩu quá 5 lần liên tiếp. Sinh viên cần liên hệ Phòng Đào tạo hoặc Phòng Công tác sinh viên để kiểm tra lý do và mở khóa.','/thong-tin-ca-nhan'),(44,'Bãi Giữ Xe Của Trường','Bãi xe trường ở đâu? Giá vé gửi xe máy UTH? Gửi xe qua đêm tại trường được không?','UTH có bãi giữ xe dành cho sinh viên tại tất cả các cơ sở. Giá vé gửi xe máy áp dụng theo đúng quy định nhà nước. Sinh viên tuyệt đối không được gửi xe qua đêm tại trường trừ các trường hợp đặc biệt được Đoàn trường hoặc Ban quản lý cơ sở cấp phép trước bằng văn bản.','/thong-tin-truong'),(45,'Miễn Giảm Anh Em Ruột','Anh em ruột cùng học UTH có được giảm học phí? Chính sách giảm học phí gia đình?','Nhà trường áp dụng chính sách hỗ trợ học phí cho gia đình có từ 2 anh/chị/em ruột trở lên đang cùng theo học hệ chính quy tại UTH. Mức giảm thường là 10% đến 20% học phí cho người em. Sinh viên cần nộp Giấy khai sinh bản sao và Đơn đề nghị về Phòng Công tác sinh viên đầu học kỳ.','/cong-thanh-toan'),(46,'Đổi Lịch Thi Học Kỳ','Làm sao để xin đổi ca thi? Bị trùng lịch thi phải làm thế nào? Trùng giờ thi xử lý sao?','Trường hợp sinh viên bị trùng lịch thi 2 môn trong cùng 1 ca hoặc có lý do bất khả kháng (tai nạn, nằm viện), sinh viên phải mang minh chứng đến Phòng Đào tạo trước ngày thi ít nhất 3 ngày để làm đơn xin chuyển ca thi hoặc đăng ký thi ghép vào đợt thi của lớp khác.','/lich-hoc-trong-tuan'),(47,'Quên Mật Khẩu Portal','Làm sao lấy lại mật khẩu Portal? Quên pass trang sinh viên UTH?','Nếu quên mật khẩu đăng nhập hệ thống Portal, sinh viên bấm vào nút \"Quên mật khẩu\" trên giao diện đăng nhập để nhận mã khôi phục qua Email sinh viên (@ut.edu.vn). Nếu không làm được, sinh viên mang Thẻ sinh viên đến trực tiếp Phòng Đào tạo để được cấp lại mật khẩu mới.','/thong-tin-ca-nhan'),(48,'Phòng Y Tế Trường','Trạm y tế trường nằm ở đâu? Khám sức khỏe sinh viên đầu năm ở đâu?','Phòng Y tế UTH nằm tại khu vực tầng trệt cơ sở chính. Đây là nơi tiếp nhận, sơ cứu và cấp phát thuốc cơ bản miễn phí cho sinh viên khi gặp các vấn đề về sức khỏe trong quá trình học tập tại trường. Đồng thời là nơi tổ chức khám sức khỏe định kỳ bắt buộc cho tân sinh viên.','/thong-tin-truong'),(49,'Học Bổng Liên Kết','Học bổng du học UTH? Chương trình trao đổi sinh viên quốc tế?','UTH liên kết với nhiều trường Đại học lớn tại Hàn Quốc, Nhật Bản, Hà Lan, Anh Quốc để triển khai các chương trình trao đổi sinh viên và học bổng du học hệ 2+2 hoặc 3+1. Sinh viên có học lực Giỏi và đạt chuẩn tiếng Anh (IELTS/TOEFL) cao sẽ được xét duyệt hồ sơ tham gia.','/thong-bao-su-kien'),(50,'Sinh Hoạt Công Dân','Tuần sinh hoạt công dân học khi nào? Không học sinh hoạt công dân có bị sao không?','Tuần sinh hoạt công dân - học sinh sinh viên được tổ chức bắt buộc vào đầu mỗi năm học. Sinh viên phải tham gia đầy đủ và làm bài kiểm tra thu hoạch đạt yêu cầu. Vắng mặt không lý do sẽ bị trừ điểm rèn luyện nghiêm khắc và xét kỷ luật tùy mức độ.','/thong-bao-su-kien'),(51,'Chuyển Cơ Sở Học Tập','Sinh viên có được đổi cơ sở học không? Đang học Quận 12 chuyển qua Bình Thạnh?','Việc phân bổ cơ sở học tập (Bình Thạnh hoặc Quận 12) phụ thuộc hoàn toàn vào chuyên ngành và kế hoạch đào tạo của từng Khoa/Viện. Sinh viên KHÔNG được tự ý xin chuyển cơ sở học tập cá nhân trừ khi có sự điều chỉnh quy hoạch lớp học từ phía Ban giám hiệu nhà trường.','/chuong-trinh-khung'),(52,'Mượn Phòng Học','Làm sao để mượn phòng học làm hoạt động? Thủ tục mượn hội trường UTH?','Các Ban cán sự lớp hoặc Câu lạc bộ muốn mượn phòng học, giảng đường hoặc Hội trường để tổ chức sinh hoạt, họp hành, tập văn nghệ phải làm Đơn xin mượn phòng (có xác nhận của Bí thư Đoàn trường hoặc Trưởng Khoa) nộp về Phòng Quản trị thiết bị trước ít nhất 2 ngày.','/dich-vu-sinh-vien'),(53,'Hỗ Trợ Khởi Nghiệp','Cuộc thi khởi nghiệp sinh viên UTH? Quỹ hỗ trợ ý tưởng sáng tạo?','Nhà trường thường xuyên tổ chức các cuộc thi Ý tưởng khởi nghiệp sáng tạo sinh viên UTH. Các dự án tiềm năng và đạt giải cao sẽ được Câu lạc bộ Khởi nghiệp của trường hỗ trợ không gian làm việc, kết nối với các quỹ đầu tư và cố vấn chuyên môn để phát triển thành dự án thực tế.','/thong-bao-su-kien'),(54,'Giấy Chứng Nhận Tạm Thời','Xin giấy chứng nhận sinh viên tạm thời ở đâu? Thời gian cấp giấy xác nhận là bao lâu?','Để phục vụ các nhu cầu cấp bách (như làm hồ sơ xin việc, chứng minh thông tin khi chưa có thẻ nhựa), sinh viên đăng ký xin cấp Giấy chứng nhận sinh viên tạm thời tại văn phòng Phòng Công tác sinh viên. Giấy xác nhận này có mộc đỏ và giá trị pháp lý ngắn hạn.','/dich-vu-sinh-vien'),(55,'Văn Phòng Đoàn Thanh Niên','Văn phòng Đoàn trường UTH ở đâu? Đăng ký sổ Đoàn, nộp sổ Đoàn ở đâu?','Văn phòng Đoàn Thanh niên - Hội Sinh viên UTH đặt tại cơ sở chính Võ Oanh. Đây là nơi quản lý toàn bộ hồ sơ đoàn viên, tiếp nhận sổ Đoàn của sinh viên đầu năm học, xét duyệt các danh hiệu thi đua, cộng điểm rèn luyện và tổ chức các chiến dịch lớn như Mùa hè xanh, Tiếp sức mùa thi.','/thong-tin-truong'),(56,'Khảo Sát Ý Kiến Sinh Viên','Khảo sát môn học làm ở đâu? Không làm khảo sát giảng viên có bị sao không?','Cuối mỗi học kỳ, UTH bắt buộc sinh viên phải tham gia Khảo sát ý kiến về hoạt động giảng dạy của giảng viên trực tuyến trên trang Portal. Sinh viên cố tình không hoàn thành khảo sát đúng hạn sẽ bị tạm khóa chức năng xem điểm thi học kỳ và khóa lịch đăng ký môn học.','/thong-tin-ca-nhan'),(57,'Đóng Lệ Phí Thi Lại','Thi lại có tốn tiền không? Lệ phí thi lại đóng ở đâu?','Đối với các môn học bị điểm F, sinh viên áp dụng quy chế học chế tín chỉ của UTH là phải đăng ký học lại và đóng tiền học phí tính theo số tín chỉ môn đó giống như học mới, trường KHÔNG tổ chức kỳ thi lại độc lập thu phí riêng như hệ niên chế cũ.','/cong-thanh-toan'),(58,'Thực Tập Tốt Nghiệp','Lịch đi thực tập của sinh viên năm cuối? Xin giấy giới thiệu thực tập ở đâu?','Sinh viên năm cuối đủ điều kiện sẽ tham gia học phần Thực tập tốt nghiệp. Sinh viên đến văn phòng Khoa/Viện chủ quản để nhận Giấy giới thiệu thực tập nộp cho doanh nghiệp. Sau khi kết thúc, phải nộp lại Báo cáo thực tập có nhận xét và mộc tròn của công ty.','/chuong-trinh-khung'),(59,'Đồ Án Tốt Nghiệp','Điều kiện được làm đồ án ra trường? Điểm GPA bao nhiêu thì được làm khóa luận tốt nghiệp?','Điều kiện để sinh viên UTH được giao đề tài làm Đồ án/Khóa luận tốt nghiệp: Tính đến học kỳ xét, sinh viên không bị cảnh báo học vụ; Tích lũy tối thiểu 80% đến 90% số tín chỉ toàn khóa; Điểm trung bình GPA đạt mức quy định riêng của từng Khoa/Viện chuyên ngành.','/chuong-trinh-khung'),(60,'Khen Thưởng Sinh Viên','Sinh viên xuất sắc được thưởng gì? Tiêu chuẩn xét khen thưởng danh hiệu học tập?','Kết thúc mỗi năm học, nhà trường tiến hành xét khen thưởng cho sinh viên đạt danh hiệu Sinh viên Xuất sắc (GPA >= 3.6/4.0) và Sinh viên Giỏi (GPA >= 3.2/4.0) kèm theo điểm rèn luyện loại Tốt trở lên. Sinh viên được tặng giấy khen của Hiệu trưởng và nhận tiền thưởng tương ứng.','/thong-bao-su-kien'),(61,'Mùa Hè Xanh UTH','Đăng ký Mùa hè xanh ở đâu? Tiêu chí tuyển chiến sĩ MHX? Đi MHX được bao nhiêu ĐRL?','Chiến dịch tình nguyện Mùa Hè Xanh UTH do Đoàn trường tổ chức vào tháng 7 hằng năm. Sinh viên đăng ký qua form chính thức của Đoàn Khoa/Viện. Tiêu chí tuyển chọn dựa trên sức khỏe, đạo đức tốt và tích cực tham gia phong trào. Hoàn thành chiến dịch được cộng tối đa 15-20 điểm rèn luyện [x].','/thong-bao-su-kien'),(62,'Tiếp Sức Mùa Thi','Đăng ký Tiếp sức mùa thi UTH? Lịch chạy chương trình TSMT?','Chương trình Tiếp sức mùa thi diễn ra vào tháng 6 hằng năm nhằm hỗ trợ thí sinh thi THPT Quốc tế. Sinh viên UTH đăng ký tham gia thông qua Hội Sinh viên trường. Chiến sĩ TSMT sẽ trực tại các điểm trường thi để phân luồng giao thông, hỗ trợ nước uống và chỉ đường.','/thong-bao-su-kien'),(63,'Xuân Tình Nguyện','Lịch chạy Xuân tình nguyện UTH? Đăng ký đi XTN ở đâu? Chi phí đóng góp XTN?','Chiến dịch Xuân Tình Nguyện UTH diễn ra vào dịp cận Tết Nguyên Đán. Các đội hình sẽ thực hiện hoạt động gói bánh chưng, tặng quà cho trẻ em cơ nhỡ, người già neo đơn và dọn dẹp nghĩa trang liệt sĩ. Sinh viên đăng ký qua Fanpage Đoàn - Hội của Khoa/Viện [x].','/thong-bao-su-kien'),(64,'Giải Chạy Sinh Viên','Giải chạy bộ UTH? Đăng ký chạy marathon trường ở đâu? Minh chứng hoàn thành giải chạy?','UTH thường xuyên tổ chức hoặc liên kết các giải chạy bộ (Marathon trực tuyến/trực tiếp qua app Strava). Sinh viên hoàn thành cự ly quy định (thường là 21km hoặc 42km tích lũy) sẽ đạt tiêu chí \"Thể lực tốt\" phục vụ xét danh hiệu Sinh viên 5 Tốt và được cộng ĐRL.','/thong-bao-su-kien'),(65,'Ngày Hội Sáng Tạo','Cuộc thi ý tưởng sáng tạo UTH? Sáng tạo trẻ sinh viên giao thông?','Ngày hội Sáng tạo trẻ UTH là sân chơi khoa học công nghệ, trưng bày các mô hình, phần mềm độc đáo do sinh viên tự nghiên cứu (robot, mô hình cầu đường, app quản lý vận tải). Đề tài đạt giải cao sẽ được hỗ trợ kinh phí tham gia các cuộc thi cấp Thành phố.','/thong-bao-su-kien'),(66,'Chiến Sĩ Tình Nguyện','Danh hiệu Chiến sĩ tình nguyện xuất sắc? Làm sao để được tặng bằng khen MHX?','Kết thúc mỗi chiến dịch tình nguyện (MHX, XTN, TSMT), Ban chỉ huy chiến dịch sẽ tổ chức họp xét để tuyên dương các cá nhân có đóng góp xuất sắc. Chiến sĩ đạt danh hiệu sẽ được tặng Giấy khen của Hiệu trưởng hoặc Ủy ban Hội Sinh viên Thành phố.','/thong-bao-su-kien'),(67,'Đại Hội Đoàn - Hội','Lịch tổ chức Đại hội Đại biểu? Đi bầu cử Đoàn Thanh niên ở đâu?','Đại hội Đại biểu Đoàn TNCS Hồ Chí Minh và Đại hội Hội Sinh viên Việt Nam trường UTH được tổ chức định kỳ để bầu ra Ban chấp hành mới. Sinh viên là Đại biểu chính thức sẽ tham gia họp và bỏ phiếu tại Hội trường lớn cơ sở chính Võ Oanh.','/thong-tin-truong'),(68,'Cắm Trại Truyền Thống','Hội trại truyền thống UTH học kỳ nào? Địa điểm cắm trại trường? Chi phí hội trại?','Hội trại truyền thống UTH thường được tổ chức nhân dịp kỷ niệm ngày thành lập Đoàn 26/03 hoặc ngày truyền thống trường. Địa điểm tổ chức có thể tại sân trường cơ sở Quận 12 hoặc các khu du lịch dã ngoại. Hội trại gồm các hoạt động dựng trại, trò chơi lớn và đêm lửa trại.','/thong-bao-su-kien'),(69,'Giải Bóng Đá UTH','Giải bóng đá nam/nữ trường UTH? Đăng ký đá banh giải trường ở đâu?','Giải bóng đá truyền thống sinh viên UTH tổ chức hằng năm tại sân bóng cỏ nhân tạo. Các đội bóng tham gia tranh tài theo đơn vị lớp hoặc Liên quân Khoa/Viện. Lịch thi đấu và thể lệ được Ban thể thao thuộc Hội sinh viên trường công bố công khai đầu học kỳ 2.','/dang-ky-hoc-phan'),(70,'Văn Nghệ Tiếng Hát','Cuộc thi tiếng hát sinh viên UTH? Cuộc thi văn nghệ UTH Got Talent?','Cuộc thi văn nghệ truyền thống (Tiếng hát sinh viên UTH) là nơi tìm kiếm các tài năng âm nhạc, nhạc cụ, nhảy hiện đại, múa dân gian. Sinh viên đăng ký tiết mục đơn ca, song ca hoặc tốp ca trực tiếp với Đội văn nghệ xung kích của trường để tham gia vòng sơ loại.','/thong-bao-su-kien'),(71,'Chiến Sĩ Đỏ - Hiến Máu','Đội tình nguyện hiến máu UTH? Câu lạc bộ Hành Trình Đỏ UTH?','Câu lạc bộ Hành Trình Đỏ / Đội Tình nguyện Hiến máu UTH là đơn vị nòng cốt phối hợp với Trung tâm hiến máu nhân đạo TP.HCM để tổ chức các đợt hiến máu tại trường. Thành viên đội sẽ hỗ trợ điều phối, hướng dẫn sinh viên điền form và chăm sóc sinh viên sau hiến máu.','/thong-tin-truong'),(72,'Minh Chứng ĐRL','Nộp minh chứng hoạt động ở đâu? Quên nộp minh chứng có được cộng điểm rèn luyện?','Khi tham gia các hoạt động bên ngoài trường (Hiến máu, Tình nguyện hè, Giải chạy), sinh viên phải giữ lại Giấy chứng nhận bản cứng hoặc chụp màn hình kết quả. Sau đó, đăng nhập hệ thống Portal nộp minh chứng đúng thời hạn quy định để Lớp trưởng xét cộng ĐRL.','/thong-tin-ca-nhan'),(73,'Điểm Rèn Luyện F','Điểm rèn luyện dưới 50 bị phạt thế nào? ĐRL loại Yếu có được tốt nghiệp không?','Sinh viên có điểm rèn luyện xếp loại Yếu (dưới 50 điểm) hoặc Kém (dưới 35 điểm) trong một năm học sẽ bị đưa vào danh sách kỷ luật cảnh cáo. Nếu bị xếp loại yếu, kém 2 học kỳ liên tiếp sẽ bị đình chỉ học tập 1 học kỳ; nếu bị lần thứ 3 sẽ bị buộc thôi học.','/thong-tin-ca-nhan'),(74,'Ngày Hội Việc Làm','UTH Job Fair tổ chức khi nào? Sinh viên năm nhất có được tham gia ngày hội việc làm?','Ngày hội việc làm UTH Job Fair diễn ra định kỳ hằng năm tại sân trường cơ sở chính. Hoạt động này thu hút hàng chục doanh nghiệp lớn đến phỏng vấn tuyển dụng trực tiếp, nhận hồ sơ thực tập. Tất cả sinh viên các năm đều được tham gia tự do để tìm kiếm cơ hội.','/thong-bao-su-kien'),(75,'Hội Thảo Kỹ Năng','Lớp học kỹ năng mềm UTH? Đăng ký chuyên đề kỹ năng ở đâu? Có tính ĐRL không?','Phòng Công tác sinh viên phối hợp với các chuyên gia tổ chức các buổi Hội thảo kỹ năng mềm (Kỹ năng viết CV, kỹ năng giao tiếp, quản lý thời gian). Sinh viên quét mã QR điểm danh tại hội trường sẽ được tự động cộng 2-3 điểm rèn luyện vào hệ thống Portal.','/dich-vu-sinh-vien'),(76,'Học phí nâng cao cho hệ Chất lượng cao (CLC)','Học phí hệ chất lượng cao là bao nhiêu? Tại sao học phí CLC lại cao hơn đại trà? Tổng tiền học phí CLC một năm?','Học phí đối với chương trình Chất lượng cao (CLC) của UTH dao động từ 900.000đ – 1.300.000đ/tín chỉ tùy thuộc vào khối ngành kỹ thuật hay kinh tế. Tổng mức học phí một năm học ước tính khoảng từ 45 đến 70 triệu đồng. Mức phí này cao hơn hệ đại trà do lớp học có quy mô nhỏ, phòng học máy lạnh hiện đại, tăng cường thời lượng tiếng Anh chuyên ngành và có các chương trình liên kết, kiến tập trực tiếp tại doanh nghiệp. [[1](https://jobsgo.vn/blog/hoc-phi-dai-hoc-giao-thong-van-tai-tphcm/)]','/cong-thanh-toan'),(77,'Quy trình chấm Điểm rèn luyện (ĐRL) hằng kỳ','Cách chấm điểm rèn luyện như thế nào? Quy trình họp xét ĐRL của lớp? Khi nào bắt đầu tự đánh giá ĐRL?','Quy trình chấm Điểm rèn luyện hằng kỳ tại UTH được thực hiện qua 3 bước bắt buộc: - Sinh viên đăng nhập hệ thống Portal tự đánh giá điểm cá nhân theo các mục quy định. - Tập thể lớp tổ chức họp dưới sự chủ trì của Ban cán sự lớp để thông qua và chấm điểm cho từng sinh viên. - Cố vấn học tập (Giảng viên chủ nhiệm) phê duyệt và gửi danh sách chính thức về Phòng Công tác sinh viên để lưu hệ thống.','/thong-tin-ca-nhan'),(78,'Thẻ bảo hiểm y tế điện tử (VssID)','Xem thẻ bảo hiểm y tế ở đâu? Cách đăng ký tài khoản VssID sinh viên? Mất thẻ bảo hiểm y tế giấy phải làm sao?','Nhà trường không cấp thẻ Bảo hiểm y tế (BHYT) bằng giấy vật lý cho sinh viên nữa. Sau khi đóng lệ phí gia hạn BHYT thành công trên cổng thanh toán của trường, sinh viên tải ứng dụng VssID (Bảo hiểm xã hội số) trên điện thoại và đăng ký tài khoản bằng mã số bảo hiểm của mình để sử dụng thẻ BHYT điện tử khi đi khám chữa bệnh tại các bệnh viện.','/dich-vu-sinh-vien'),(79,'Chuẩn tin học quốc tế nâng cao','Chứng chỉ tin học IC3 hay MOS tốt hơn? Quy đổi điểm tin học đầu ra như thế nào?','UTH công nhận cả hai chứng chỉ quốc tế là MOS và IC3 để xét đạt chuẩn đầu ra Tin học. Đối với chứng chỉ MOS, sinh viên phải đạt từ 3 kỹ năng độc lập trở lên (gồm Word, Excel và Powerpoint). Đối với chứng chỉ IC3, sinh viên phải thi đạt cả 3 phần (Living Online, Key Applications, và Computing Fundamentals). Sinh viên mang chứng chỉ gốc đến Phòng Đào tạo để làm thủ tục hậu kiểm công nhận quy đổi.','/dich-vu-sinh-vien'),(80,'Quy định sử dụng mạng Wifi nội bộ của trường','Cách kết nối wifi trường UTH? Mật khẩu wifi sinh viên là gì? Tại sao không vào được wifi trường?','Nhà trường cấp hệ thống mạng Wifi miễn phí tại tất cả các khu vực giảng đường, thư viện và sân trường cho sinh viên. Để kết nối, sinh viên chọn mạng Wifi dành riêng cho người học, sau đó đăng nhập bằng Mã số sinh viên (Username) và Mật khẩu Portal cá nhân của mình. Hệ thống sẽ tự động chặn các truy cập vào trang web độc hại hoặc tải tài liệu lậu dung lượng quá lớn làm nghẽn băng thông.','/thong-tin-truong'),(81,'Đăng ký tham gia Câu lạc bộ (CLB) đầu năm học','Làm sao để vào câu lạc bộ của trường? Ngày hội các câu lạc bộ tổ chức khi nào? Tuyển thành viên CLB UTH?','Vào khoảng tháng 9 và tháng 10 hằng năm (đầu học kỳ 1), Hội Sinh viên trường UTH tổ chức Ngày hội các Câu lạc bộ (CLB Festival) tại sân trường cơ sở chính. Tại đây, tất cả các CLB (Học thuật, Nghệ thuật, Thể thao, Tình nguyện) sẽ đặt gian hàng giới thiệu và phát đơn tuyển thành viên mới trực tiếp hoặc trực tuyến qua các trang Fanpage chính thức của mình.','/thong-bao-su-kien'),(82,'Đăng ký cấp lại tài khoản Email sinh viên (@ut.edu.vn)','Làm sao để đổi mật khẩu email sinh viên? Bị mất email của trường xử lý thế nào?','Email sinh viên định dạng [MSSV]@ut.edu.vn được nhà trường cấp miễn phí cho toàn bộ người học để liên lạc và nhận các thông báo quan trọng. Nếu bị khóa tài khoản hoặc quên mật khẩu email, sinh viên mang Thẻ sinh viên đến trực tiếp văn phòng Trung tâm Dữ liệu và Công nghệ thông tin của trường tại khu nhà chức năng cơ sở chính để được hỗ trợ reset cấp lại mật khẩu ngay trong ngày.','/thong-tin-ca-nhan'),(83,'Hoạt động \"Hiến máu tình nguyện\" lần 2 trong năm','Một năm trường tổ chức hiến máu mấy lần? Lịch hiến máu đợt 2 của trường?','Nhằm đáp ứng nhu cầu cung cấp máu cứu người, Đoàn trường và Hội sinh viên UTH phối hợp tổ chức hoạt động hiến máu nhân đạo định kỳ 2 lần trong một năm học (thường rơi vào Học kỳ 1 và Học kỳ 2). Lịch chi tiết của từng đợt sẽ được đăng tải sớm trên trang Portal trước 1 tuần để sinh viên đăng ký tham gia và nhận quyền lợi cộng điểm rèn luyện.','/thong-bao-su-kien'),(84,'Chế độ miễn giảm học phí cho con em diện chính sách','Con thương binh có được giảm học phí không? Thủ tục xin miễn học phí diện hộ nghèo? Nộp hồ sơ giảm học phí ở đâu?','Sinh viên thuộc diện con thương binh, bệnh binh, người có công với cách mạng, sinh viên dân tộc thiểu số vùng đặc biệt khó khăn, hoặc sinh viên thuộc hộ nghèo/hộ cận nghèo sẽ được hưởng chính sách miễn hoặc giảm học phí theo đúng quy định của Nhà nước. Sinh viên cần chuẩn bị Sổ hộ nghèo, Giấy chứng nhận diện chính sách bản công chứng nộp về Phòng Công tác sinh viên để xét duyệt đầu năm học.','/cong-thanh-toan'),(85,'Quy định mượn học cụ, thiết bị tại phòng thí nghiệm','Làm sao để mượn đồ phòng thí nghiệm làm đồ án? Quy định mượn thiết bị đo đạc?','Sinh viên các ngành kỹ thuật (như Công trình, Điện - Điện tử, CNTT) cần mượn thiết bị, học cụ tại các phòng thí nghiệm, xưởng thực hành để làm đồ án hoặc bài tập lớn phải có Giấy đề xuất mượn thiết bị do Giảng viên hướng dẫn ký duyệt. Sinh viên nộp giấy này cho Cán bộ quản lý phòng thí nghiệm, xuất trình Thẻ sinh viên để ký sổ mượn và có trách nhiệm bảo quản, hoàn trả nguyên vẹn đúng thời hạn.','/dich-vu-sinh-vien'),(86,'Tiếp nhận hồ sơ Đăng ký xét tuyển Học bạ đợt tiếp theo','Khi nào trường nhận hồ sơ học bạ đợt 2? Cách nộp học bạ online vào trường UTH?','Hội đồng tuyển sinh UTH tổ chức xét tuyển học bạ THPT thành nhiều đợt trong năm. Thí sinh đăng ký nộp hồ sơ trực tuyến thông qua trang Tuyển sinh chính thức của trường, điền đầy đủ điểm số các môn thuộc tổ hợp xét tuyển và tải ảnh chụp học bạ lên hệ thống. Sau khi có kết quả trúng tuyển tạm thời, thí sinh phải nộp hồ sơ bản giấy về trường để đối chiếu xác thực thông tin.','/thong-bao-su-kien'),(87,'Thủ tục xin tạm hoãn thi học kỳ','Bị ốm đột xuất không đi thi được làm sao? Cách xin hoãn thi học kỳ? Đơn xin hoãn thi nộp ở đâu?','Nếu gặp lý do bất khả kháng như tai nạn hoặc bệnh tật phải nằm viện điều trị ngay vào ngày thi kết thúc học phần, sinh viên phải làm Đơn xin hoãn thi kèm theo Giấy ra viện hoặc Giấy xác nhận có mộc tròn của bệnh viện nộp về Phòng Đào tạo trong vòng tối đa 3 ngày làm việc kể từ ngày thi của môn đó. Môn học xin hoãn thi thành công sẽ được chuyển điểm sang đợt thi bổ sung hoặc thi ghép cùng khóa sau mà không bị tính điểm 0.','/lich-hoc-trong-tuan'),(88,'Quy chế quản lý thông tin và tài sản số của sinh viên','Có được chia sẻ tài khoản Portal cho người khác không? Quy định bảo mật thông tin sinh viên UTH?','Theo quy định an ninh thông tin của UTH, tài khoản Portal và mật khẩu cá nhân là tài sản số độc quyền của cá nhân sinh viên đó. Sinh viên tuyệt đối không được chia sẻ tài khoản này cho bất kỳ ai khác. Mọi hành vi tự ý chia sẻ tài khoản dẫn đến việc sai lệch dữ liệu đăng ký môn học, kết quả học tập hoặc phát tán thông tin sai sự thật trên hệ thống sẽ bị xử lý kỷ luật nghiêm khắc từ mức cảnh cáo đến đình chỉ học tập.','/thong-tin-ca-nhan'),(89,'Quy định tham quan kiến tập thực tế tại doanh nghiệp','Sinh viên năm mấy được đi kiến tập? Đi kiến tập doanh nghiệp có bắt buộc không?','Hoạt động tham quan kiến tập thực tế tại doanh nghiệp, nhà máy, cảng biển là một học phần bắt buộc hoặc hoạt động bổ trợ bổ ích được các Khoa/Viện tổ chức cho sinh viên (thường dành cho sinh viên năm 2 hoặc năm 3). Hoạt động này giúp sinh viên tiếp cận môi trường làm việc thực tế. Sinh viên tham gia phải tuân thủ nghiêm ngặt giờ giấc điều phối của giảng viên trưởng đoàn và mặc đồng phục trường lịch sự.','/chuong-trinh-khung'),(90,'Tư vấn tâm lý và hỗ trợ sinh viên gặp áp lực học đường','Trường có phòng tư vấn tâm lý không? Bị stress áp lực học tập thì liên hệ ai hỗ trợ?','Nhằm hỗ trợ giải tỏa các áp lực về học tập, cuộc sống hoặc các vấn đề tâm lý cá nhân, UTH có Trung tâm Tư vấn tâm lý sinh viên trực thuộc Phòng Công tác sinh viên. Tại đây, các chuyên gia tâm lý sẽ lắng nghe, chia sẻ và tư vấn định hướng hoàn toàn miễn phí và bảo mật tuyệt đối thông tin cho sinh viên. Sinh viên có thể đặt lịch hẹn tư vấn trực tuyến qua trang hỗ trợ hoặc đến gặp trực tiếp tại văn phòng nhà A.','/dich-vu-sinh-vien'),(106,'Rút hồ sơ thôi học','rut ho so, thoi hoc, xoa ten, khong hoc nua, xin thoi hoc, nghi hoc luon','Sinh viên muốn xin thôi học và rút hồ sơ gốc (Học bạ, Bằng tốt nghiệp THPT) phải làm đơn theo mẫu của trường, xin ý kiến xác nhận không nợ sách Thư viện, không nợ học phí, sau đó nộp về Phòng Đào tạo để ra quyết định xóa tên và trả lại hồ sơ.','/dich-vu-sinh-vien'),(107,'Đăng ký thi lại chuẩn đầu ra','thi lai anh van, thi lai tin hoc, nop don thi lai cdr, dang ky thi tieng anh','Trung tâm Ngoại ngữ và Trung tâm Tin học UTH tổ chức các đợt thi đánh giá chuẩn đầu ra định kỳ hằng tháng. Sinh viên theo dõi lịch thông báo, đăng ký và đóng lệ phí dự thi trực tuyến trên trang của Trung tâm trước ngày thi ít nhất 10 ngày.','/thong-bao-su-kien'),(108,'Xét giảm điểm rèn luyện','tru diem ren luyen, khieu nai drl, mo cong drl, cham lai drl, kieu nai drl','Nếu phát hiện điểm rèn luyện hiển thị trên Portal bị sai sót hoặc bị trừ điểm không rõ lý do, sinh viên làm đơn khiếu nại gửi Ban cán sự lớp và Cố vấn học tập trong thời gian 5 ngày kể từ khi công bố kết quả dự kiến để được kiểm tra, điều chỉnh.','/thong-tin-ca-nhan'),(109,'Quy trình vay vốn ngân hàng','vay von ngan hang, giay xac nhan vay von, ngan hang chinh sach, don xin vay von','Sinh viên thuộc diện đối tượng được vay vốn tín dụng học tập mang hộ khẩu và minh chứng đối tượng đến Phòng Công tác sinh viên để xin cấp \"Giấy xác nhận là sinh viên của trường\". Sau đó mang giấy này về địa phương để làm thủ tục giải ngân tại Ngân hàng Chính sách Xã hội.','/dich-vu-sinh-vien'),(110,'Chính sách Học bổng tuyển sinh','hoc bong tuyen sinh, thu khoa, kien quoc, hoc bong dau vao, khuyen khich dau vao','UTH cấp học bổng toàn phần hoặc bán phần (miễn 50% - 100% học phí năm đầu) cho các tân sinh viên đạt danh hiệu Thủ khoa trường, Thủ khoa ngành, hoặc các thí sinh đạt điểm cao xuất sắc trong kỳ thi tốt nghiệp THPT và kỳ thi Đánh giá năng lực.','/thong-bao-su-kien'),(111,'Thời gian giữ xe tối đa tại trường','gui xe qua dem, mat xe, quen lay xe, giu xe may, bai xe mo cua den may gio','Bãi giữ xe trường UTH mở cửa từ 6h00 đến 22h00 hằng ngày. Sinh viên không được để xe lại bãi qua đêm. Trường hợp xe bị hư hỏng bắt buộc phải để lại, sinh viên phải báo cáo và đăng ký thông tin với Đội bảo vệ trực ban của trường để được quản lý.','/thong-tin-truong'),(112,'Thủ tục phúc khảo điểm quá trình','phuc khao diem thanh phan, xem lai diem giua ky, diem qua trinh bi sai, sửa điểm','Điểm quá trình (điểm chuyên cần, bài tập, giữa kỳ) do Giảng viên bộ môn quản lý và công bố trên lớp. Nếu có thắc mắc, sinh viên phải phản hồi trực tiếp với Giảng viên trước khi môn học kết thúc. Khi điểm đã nộp về trường, giảng viên mới không thể tự ý chỉnh sửa.','/ket-qua-hoc-tap'),(113,'Tham gia hiến máu có được nghỉ học','hien mau co duoc nghi, xin nghi hoc hien mau, hoãn hoc hien mau','Sinh viên tham gia ngày hội hiến máu tình nguyện tổ chức tại trường sẽ được hỗ trợ cấp Giấy chứng nhận hiến máu. Giấy này được dùng làm minh chứng hợp lệ để xin phép nghỉ học có lý do đối với các tiết học diễn ra trong ngày hiến máu đó.','/lich-hoc-trong-tuan'),(114,'Đổi thẻ nhựa sang thẻ sinh viên','doi the nhua, lam the sinh vien moi, chip the sinh vien, tich hop the ngan hang','Hiện nay UTH triển khai cấp thẻ sinh viên tích hợp thẻ ngân hàng thông minh. Sinh viên năm nhất nhận thẻ theo lịch phân phối của phòng CTSV. Sinh viên khóa cũ có nhu cầu đổi phôi thẻ lỗi sang thẻ đa năng mới đăng ký và đóng phí tại văn phòng phòng CTSV.','/dich-vu-sinh-vien'),(115,'Hủy tư cách đoàn viên','xoa ten doan, rut so doan, khong sinh hoat doan, dong doan phi','Đoàn viên không tham gia sinh hoạt Đoàn hoặc không đóng đoàn phí liên tục trong 3 tháng mà không có lý do chính đáng sẽ bị xem xét xóa tên khỏi danh sách Đoàn viên và thông báo về Chi đoàn lớp sinh hoạt để trừ điểm rèn luyện theo quy chế.','/thong-tin-ca-nhan'),(116,'Chính sách hỗ trợ bảo hiểm tai nạn','bao hiem tai nan, bhtn, bi tai nan duoc den bao nhieu, ho tro nam vien','Ngoài BHYT bắt buộc, nhà trường có liên kết đơn vị bảo hiểm để sinh viên đăng ký tự nguyện Bảo hiểm tai nạn. Khi xảy ra sự cố chấn thương, nằm viện, sinh viên mang Giấy ra viện và hóa đơn chi phí đến Phòng Công tác sinh viên để làm thủ tục nhận tiền bảo hiểm bồi thường.','/dich-vu-sinh-vien'),(117,'Mượn thiết bị âm thanh, sự kiện','muon loa keo, loa mic, thiet bi su kien, loa mic clb, thiet bi doan hoi','Các Câu lạc bộ, Chi đoàn lớp cần mượn loa kéo, micro, thiết bị âm thanh hoặc backdrop để tổ chức hoạt động phong trào phải làm đơn đăng ký thông qua Văn phòng Đoàn trường hoặc Phòng Quản trị thiết bị trước ngày diễn ra sự kiện ít nhất 3 ngày.','/dich-vu-sinh-vien'),(118,'Cấp lại giấy chứng nhận quốc phòng','mat bang quan su, mat giay quoc phong, cap lai chung chi gdqp, xin bang diem gdqp','Chứng chỉ Giáo dục Quốc phòng - An ninh do Trung tâm GDQP cấp gốc 1 lần duy nhất. Nếu bị mất, sinh viên không được cấp lại bằng gốc mà phải làm đơn xin cấp Giấy xác nhận hoàn thành môn học hoặc bản sao bảng điểm trực tiếp tại Trung tâm quản lý để nộp xét tốt nghiệp.','/dich-vu-sinh-vien'),(119,'Đăng ký tham gia hiến máu đợt hè','hien mau mua he, hien mau hk he, lich hien mau thang 6 thang 7','Hoạt động hiến máu tình nguyện đợt hè thường được phối hợp tổ chức vào khoảng tháng 6 hoặc tháng 7 nhằm bổ sung nguồn máu dự trữ khan hiếm. Sinh viên học kỳ hè hoặc sinh viên ở lại thành phố đăng ký trực tuyến qua Fanpage Hội Sinh viên trường UTH.','/thong-bao-su-kien'),(120,'Quy định số lần cảnh báo học vụ','bi canh bao may lan thi bi duoi, gioi han canh bao, canh bao hoc vu muc do 2','Theo quy chế học vụ UTH, sinh viên bị cảnh báo học vụ 2 lần liên tiếp sẽ bị buộc thôi học. Nếu bị cảnh báo rải rác không liên tiếp, sinh viên vẫn được tiếp tục học nhưng phải chủ động gặp Cố vấn học tập để làm cam kết lộ trình cải thiện điểm số.','/thong-tin-ca-nhan'),(121,'Thời hạn sử dụng của thẻ thư viện','gia han the thu vien, the thu vien het han, khoa the thu vien','Thẻ thư viện UTH (tích hợp trên Thẻ sinh viên) có giá trị sử dụng xuyên suốt toàn bộ khóa học chính quy của sinh viên tại trường. Tài khoản thư viện sẽ tự động bị khóa sau khi sinh viên nhận quyết định tốt nghiệp hoặc quyết định thôi học, ngừng học.','/dich-vu-sinh-vien'),(122,'Thủ tục xin miễn học thể dục','mien hoc the duc, khong hoc the duc bi khuyet tat, don mien giao duc the chat','Sinh viên có khuyết tật, dị tật hoặc mắc các bệnh lý mãn tính không thể tham gia vận động mạnh phải làm đơn xin miễn/giảm học phần Giáo dục thể chất kèm theo Bệnh án, Giấy chứng nhận thương tật của bệnh viện cấp Quận trở lên nộp về Bộ môn GDTC để xét duyệt chuyển đổi môn học phù hợp.','/dang-ky-hoc-phan'),(123,'Thời gian nhận bằng tốt nghiệp','khi nao nhan bang goc, lay bang tot nghiep o dau, phat bang tot nghiep','Bằng tốt nghiệp chính thức được cấp phát cho sinh viên trong vòng 30 ngày kể từ ngày ký Quyết định công nhận tốt nghiệp. Sinh viên nhận bằng trực tiếp tại lễ tốt nghiệp hoặc đến văn phòng Phòng Đào tạo để ký sổ nhận bằng gốc (mang theo CCCD).','/thong-bao-su-kien'),(124,'Phí phạt nợ học phí quá hạn','nop tre hoc phi, nop phat hoc phi, tre han dong tien hoc bi phat bao nhieu','UTH không áp dụng hình thức phạt tiền mặt khi sinh viên nộp học phí trễ hạn. Tuy nhiên, sinh viên không hoàn thành học phí đúng thời gian quy định sẽ bị hệ thống tự động khóa tài khoản Portal, hủy danh sách đăng ký học phần và cấm tham gia kỳ thi học kỳ.','/cong-thanh-toan'),(125,'Xin hoãn đi thực tập tốt nghiệp','hoan thuc tap, don xin hoan thuc tap nam cuoi, doi lich di thuc tap','Sinh viên năm cuối vì lý do sức khỏe hoặc chưa tích lũy đủ các môn học điều kiện bắt buộc muốn xin hoãn học phần Thực tập tốt nghiệp phải làm đơn xin hoãn nộp về Văn phòng Khoa/Viện chủ quản trước khi danh sách phân công đơn vị thực tập được công bố.','/chuong-trinh-khung'),(126,'Chính sách hỗ trợ sinh viên nghèo','tro cap kho khan, ho tro sinh vien ngheo đột xuất, tro cap xa hoi','Sinh viên gặp tai nạn, thiên tai, hỏa hoạn hoặc gia đình gặp biến cố lớn đột xuất dẫn đến hoàn cảnh đặc biệt khó khăn làm đơn xin hỗ trợ gửi Phòng Công tác sinh viên. Nhà trường sẽ xem xét trích Quỹ hỗ trợ sinh viên để cấp kinh phí trợ cấp đột xuất.','/dich-vu-sinh-vien'),(127,'Đồ án tốt nghiệp đạt điểm F xử lý sao','rot do an tot nghiep, lam lai khoa luan, rot khoa luan ra truong','Sinh viên bảo vệ Đồ án hoặc Khóa luận tốt nghiệp nhận điểm F (không đạt) sẽ không được tốt nghiệp đúng hạn. Sinh viên bắt buộc phải đăng ký làm lại đề tài mới hoặc đăng ký lại học phần đồ án vào kỳ xét duyệt tiếp theo của năm học sau và đóng phí theo quy định.','/chuong-trinh-khung'),(128,'Quy chế xét học bổng khi nợ môn','no mon co duoc hoc bong, rot mon co duoc xet hoc bong, thi lai co duoc hoc bong','Theo quy chế khen thưởng của UTH, sinh viên chỉ cần nợ 1 môn học (nhận điểm F) hoặc đăng ký thi lại/học lại bất kỳ môn nào trong học kỳ đó thì sẽ lập tức bị tước quyền tham gia xét duyệt Học bổng khuyến khích học tập, bất kể điểm GPA tổng của bạn cao bao nhiêu.','/thong-bao-su-kien'),(129,'Liên hệ Ban quản lý ký túc xá','so dien thoai ban quan ly ktx, gap ai de phan anh ktx, ban quan ly noi tru','Để phản ánh các vấn đề về điện nước, an ninh phòng ở hoặc nộp chi phí nội trú Ký túc xá, sinh viên đến trực tiếp văn phòng Ban quản lý nội trú Ký túc xá đặt tại khu vực cổng vào của khu nội trú cơ sở đó để được cán bộ trực ban giải quyết.','/thong-tin-truong'),(131,'Phương thức tuyển sinh năm 2026 của UTH','phương thức tuyển sinh 2026, phuong thuc tuyen sinh 2026, uth xet tuyen cach nao, xet hoc ba 2026, diem thi thpt 2026','Năm 2026, UTH áp dụng các phương thức tuyển sinh chính bao gồm: Xét tuyển thẳng theo quy định của Bộ GD&ĐT; Xét tuyển dựa trên kết quả kỳ thi tốt nghiệp THPT năm 2026; Xét tuyển học bạ THPT (điểm trung bình tổ hợp môn 5 học kỳ hoặc cả năm lớp 12); và Xét tuyển dựa trên kết quả kỳ thi Đánh giá năng lực của ĐHQG TP.HCM.','/thong-bao-su-kien'),(132,'Các tổ hợp môn xét tuyển phổ biến tại UTH','tổ hợp môn xét tuyển, to hop mon xet tuyen, khoi thi vao uth, khoi a00 a01 d01 d07, uth xet khoi nao','Các ngành đào tạo tại UTH xét tuyển chủ yếu qua các tổ hợp môn: A00 (Toán, Lý, Hóa), A01 (Toán, Lý, Tiếng Anh), D01 (Toán, Văn, Tiếng Anh), và D07 (Toán, Hóa, Tiếng Anh). Riêng các ngành Công nghệ thông tin và Logistics ưu tiên chỉ tiêu rất lớn cho tổ hợp A00 và A01.','/chuong-trinh-khung'),(133,'Điểm chuẩn ngành Công nghệ thông tin (CNTT) năm 2025','điểm chuẩn cntt 2025, diem chuan cong nghe thong tin 2025, nganh cntt uth bao nhieu diem, diem trung tuyen cntt','Điểm chuẩn trúng tuyển theo phương thức xét điểm thi tốt nghiệp THPT năm 2025 của ngành Công nghệ thông tin (Hệ đại trà) tại UTH là 24.50 điểm. Đối với hệ Chất lượng cao, điểm chuẩn dao động quanh mức 23.00 điểm.','/chuong-trinh-khung'),(134,'Điểm chuẩn ngành Logistics và Quản lý chuỗi cung ứng năm 2025','điểm chuẩn logistics 2025, diem chuan logistics 2025, nganh logistics lay bao nhieu diem, diem xet tuyen logistics','Logistics và Quản lý chuỗi cung ứng là một trong những ngành có điểm chuẩn cao nhất trường UTH. Năm 2025, điểm chuẩn phương thức xét điểm thi THPT của ngành này là 25.25 điểm đối với hệ đại trà và 23.75 điểm đối với hệ chất lượng cao.','/chuong-trinh-khung'),(135,'Điểm chuẩn xét học bạ năm 2025 (Tham khảo cho năm 2026)','điểm chuẩn học bạ 2025, diem chuan hoc ba 2025, xet hoc ba uth bao nhieu diem, diem hoc ba nganh cao nhat','Điểm chuẩn xét tuyển bằng học bạ THPT năm 2025 của UTH dao động từ 18.00 đến 27.50 điểm (tổng điểm 3 môn trong tổ hợp cộng điểm ưu tiên). Các ngành thuộc khối Kinh tế, CNTT và Logistics yêu cầu mức điểm học bạ từ 25.00 điểm trở lên mới có cơ hội trúng tuyển.','/thong-bao-su-kien'),(136,'Chỉ tiêu tuyển sinh dự kiến năm 2026','chỉ tiêu tuyển sinh 2026, chi tieu tuyen sinh 2026, uth tuyen bao nhieu sinh vien, chi tieu nganh cntt 2026','Năm 2026, Trường Đại học Giao thông Vận tải TP.HCM dự kiến tuyển sinh khoảng 5.000 đến 6.000 chỉ tiêu cho tất cả các ngành đào tạo tại các cơ sở. Trong đó, khối ngành kỹ thuật công trình, logistics và công nghệ thông tin chiếm hơn 50% tổng chỉ tiêu của toàn trường.','/thong-tin-truong'),(137,'Cách quy đổi điểm chứng chỉ IELTS trong tuyển sinh UTH','quy đổi điểm ielts, quy doi diem ielts tuyen sinh, ielts 5.5 duoc may diem, cong diem ielts vao uth','UTH áp dụng quy đổi điểm tiếng Anh đối với thí sinh có chứng chỉ IELTS quốc tế còn hạn sử dụng thay thế cho điểm thi THPT. Cụ thể: IELTS 5.0 quy đổi thành 8.5 điểm; IELTS 5.5 quy đổi thành 9.0 điểm; IELTS 6.0 quy đổi thành 9.5 điểm; và IELTS từ 6.5 trở lên được quy đổi thành 10 điểm môn Tiếng Anh.','/dich-vu-sinh-vien'),(138,'Điểm sàn nhận hồ sơ xét tuyển (Ngưỡng đảm bảo chất lượng)','điểm sàn uth, diem san nhan ho so, bao nhieu diem thi duoc nop don, diem san 2025 2026','Ngưỡng đảm bảo chất lượng đầu vào (Điểm sàn) nhận hồ sơ đăng ký xét tuyển theo điểm thi tốt nghiệp THPT của UTH thường được công bố sau khi có kết quả thi. Mức sàn trung bình các năm dao động từ 15.00 đến 19.00 điểm tùy theo ngành học và hệ đào tạo.','/thong-bao-su-kien'),(139,'Đăng ký nguyện vọng vào UTH trên hệ thống của Bộ GD&ĐT','đăng ký nguyện vọng, dang ky nguyen vong, ma truong uth la gi, xep nguyen vong vao uth','Để xét tuyển vào UTH bằng điểm thi THPT, thí sinh phải đăng ký nguyện vọng trên hệ thống chung của Bộ GD&ĐT theo đúng lịch quy định. Thí sinh cần nhập chính xác Mã trường của UTH là GTS và chọn đúng mã ngành, mã tổ hợp môn mong muốn. Nên xếp ngành yêu thích nhất ở Nguyện vọng 1.','/thong-bao-su-kien'),(140,'Lệ phí xét tuyển hồ sơ đầu vào','lệ phí xét tuyển, le phi xet tuyen, nop tien xet hoc ba bao nhieu, dong tien nguyen vong','Lệ phí xét tuyển đối với phương thức xét học bạ nộp trực tiếp về trường UTH áp dụng theo quy định hành chính thu chi. Đối với phương thức xét điểm thi THPT, thí sinh đóng lệ phí trực tuyến trực tiếp trên hệ thống cổng thông tin của Bộ GD&ĐT khi tiến hành xác nhận số lượng nguyện vọng.','/cong-thanh-toan'),(141,'Thời gian công bố kết quả trúng tuyển chính thức','khi nào biết kết quả trúng tuyển, khi nao biet ket qua trung tuyen, lich cong bo diem chuan uth','Thời gian công bố điểm chuẩn và danh sách trúng tuyển chính thức của UTH tuân thủ nghiêm ngặt theo lộ trình chung của Bộ GD&ĐT (thường vào khoảng tháng 8 hằng năm). Kết quả xét tuyển sớm bằng học bạ thường được trường thông báo trước đó vào tháng 6 hoặc tháng 7.','/thong-bao-su-kien'),(142,'Thủ tục xác nhận nhập học trực tuyến','xác nhận nhập học, xac nhan nhap hoc online, huong dan nhap hoc uth, khong xac nhan nhap hoc bi gi','Sau khi có thông báo trúng tuyển chính thức, thí sinh bắt buộc phải thực hiện bước Xác nhận nhập học trực tuyến trên hệ thống của Bộ GD&ĐT trước thời hạn quy định. Thí sinh cố tình không xác nhận nhập học đúng hạn sẽ bị hệ thống tự động hủy kết quả trúng tuyển vào trường.','/dich-vu-sinh-vien'),(143,'Hồ sơ bản giấy cần chuẩn bị khi đến trường làm thủ tục nhập học','hồ sơ nhập học cần gì, ho so nhap hoc can gi, mang theo gi khi nhap hoc uth, giay to nhap hoc','Hồ sơ nhập học bản giấy nộp tại trường bao gồm: Giấy báo trúng tuyển bản gốc; Học bạ THPT (bản sao công chứng); Giấy chứng nhận tốt nghiệp tạm thời hoặc Bằng tốt nghiệp THPT; Bản sao CCCD; Giấy khai sinh; và các giấy tờ minh chứng đối tượng ưu tiên chính sách (nếu có).','/dich-vu-sinh-vien'),(144,'Quy trình làm thủ tục nhập học trực tiếp tại trường','quy trình nhập học trực tiếp, quy trinh nhap hoc truc tiep, den truong nhap hoc o dau, huong dan tan sinh vien','Khi đến nhập học trực tiếp tại cơ sở chính của UTH, tân sinh viên thực hiện theo quy trình luồng: - Tra cứu số thứ tự và phòng làm thủ tục tại sảnh hướng dẫn. - Nộp hồ sơ bản giấy tại bàn tiếp nhận của Khoa/Viện. - Đóng học phí và các khoản bảo hiểm bắt buộc tại bàn tài chính. - Nhận lịch học Tuần sinh hoạt công dân và chụp ảnh làm Thẻ sinh viên.','/thong-tin-truong'),(145,'Chính sách rút hồ sơ hoàn học phí đối với tân sinh viên','rút học phí nhập học, rut hoc phi nhap hoc, nhap hoc roi xin rut lai tien, thoi hoc rut lai hoc phi','Tân sinh viên đã làm thủ tục nhập học nhưng vì lý do cá nhân muốn xin rút hồ sơ không theo học nữa sẽ được xem xét hoàn trả học phí tùy theo thời điểm nộp đơn. Nếu nộp đơn rút trước ngày khai giảng chính thức, sinh viên được hoàn lại một phần học phí theo quy định đóng rút bồi hoàn của nhà trường; sau ngày khai giảng sẽ không được hoàn phí.','/cong-thanh-toan');
/*!40000 ALTER TABLE `faq` ENABLE KEYS */;
UNLOCK TABLES;

