INSERT INTO `tickets` VALUES (1,'Phạm Anh Tuấn','075205019210','Hỗ trợ về: Học phí hệ chất lượng cao...','Cho em hỏi học phí chất lượng cao học kỳ hè tính như thế nào ạ? Có giống học kỳ chính không?','pending',NULL,'2026-07-01 01:04:40'),(2,'Phạm Anh Tuấn','075205019210','Hỗ trợ về: Cách tính điểm rèn luyện...','Thưa thầy cô, em tham gia hiến máu tình nguyện thì được cộng bao nhiêu điểm rèn luyện và nộp minh chứng ở đâu ạ?','read','Chào em, hiến máu tình nguyện được cộng 5 điểm rèn luyện. Em nộp minh chứng trực tuyến trên Portal sinh viên nhé.','2026-06-30 03:04:40');
